def _result(statements):
    def key_function(statement):
        return tuple(key(statement))
    return list(toolz.reduceby(key_function, Statement.merge, statements).values())

def merge(self, other):
    """Merge two statements into one."""
    if self.Effect != other.Effect:
        raise ValueError(f"Trying to combine two statements with differing effects: {self.Effect} {other.Effect}")

    effect = self.Effect

    actions = list(sorted(set(self.Action + other.Action), key=lambda action: action.json_repr()))
    resources = list(sorted(set(self.Resource + other.Resource)))

    return Statement(
        Effect=effect,
        Action=actions,
        Resource=resources,
    )

def _source_to_iam_prefix(self):
    special_cases = {
        'monitoring.amazonaws.com': 'cloudwatch',
        'appstream2.amazonaws.com': 'appstream',
        'models.lex.amazonaws.com': 'lex',
        'runtime.lex.amazonaws.com': 'lex',
        'mturk-requester.amazonaws.com': 'mechanicalturk',
        'streams.dynamodb.amazonaws.com': 'dynamodb',
        'tagging.amazonaws.com': 'tag',
    }

    default_case = self.event_source.split('.')[0]

    return special_cases.get(self.event_source, default_case)

def to_statement(self):
    """Converts record into a matching IAM Policy Statement"""
    if self.event_source == "sts.amazonaws.com" and self.event_name == "GetCallerIdentity":
        return None

    if self.event_source == "apigateway.amazonaws.com":
        return self._to_api_gateway_statement()

    return Statement(
        Effect="Allow",
        Action=[Action(self._source_to_iam_prefix(), self._event_name_to_iam_action())],
        Resource=sorted(self.resource_arns)
    )

def parse_human_readable_time(time_string):
    """Parse human readable strings (e.g. "now", "2017-01-01" and "one hour ago") into datetime"""
    return dateparser.parse(time_string, settings={'RETURN_AS_TIMEZONE_AWARE': True})

def default(self, o):  # pylint: disable=method-hidden
    if hasattr(o, 'json_repr'):
        return o.json_repr()
    return json.JSONEncoder.default(self, o)

def _parse_statement(statement):
    return Statement(Action=[_parse_action(action) for action in statement['Action']],
                     Effect=statement['Effect'],
                     Resource=statement['Resource'])

def parse_policy_document(stream):
    """Parse a stream of JSON data to a PolicyDocument object"""
    if isinstance(stream, six.string_types):
        json_dict = json.loads(stream)
    else:
        json_dict = json.load(stream)

    return PolicyDocument(_parse_statements(json_dict['Statement']), Version=json_dict['Version'])

def _guess_actions(actions, allowed_prefixes):
    return [item for action in actions
            for item in action.matching_actions(allowed_prefixes)]

def _extend_statement(statement, allowed_prefixes):
    extended_actions = _guess_actions(statement.Action, allowed_prefixes)
    if extended_actions:
        return [statement, Statement(Action=extended_actions,
                                     Effect=statement.Effect,
                                     Resource=["*"])]

    return [statement]

def guess_statements(policy, allowed_prefixes):
    """Guess additional create actions"""
    extended_statements = [item for statement in policy.Statement
                           for item in _extend_statement(statement, allowed_prefixes)]

    return PolicyDocument(Version=policy.Version, Statement=extended_statements)

def _base_action(self):
    without_prefix = self.action
    for prefix in BASE_ACTION_PREFIXES:
        without_prefix = re.sub(prefix, "", without_prefix)

    without_plural = re.sub(r"s$", "", without_prefix)

    return without_plural

def _parse_action(action):
    parts = action.split(":")
    return Action(parts[0], parts[1])

def all_known_iam_permissions():
    "Return a list of all known IAM actions"
    with open(os.path.join(os.path.dirname(__file__), 'known-iam-actions.txt'), encoding="UTF-8") as iam_file:
        return {line.rstrip('\n') for line in iam_file.readlines()}

def _to_paths(triple):
    root, _, files_in_dir = triple
    return [os.path.join(root, file_in_dir) for file_in_dir in files_in_dir]

def filename(self):
    """Name of the logfile (without path)"""
    return os.path.split(self._path)[-1]

def has_valid_filename(self):
    """Returns if the log file represented has a valid filename"""
    pattern = re.compile(r"[0-9]+_CloudTrail_[a-z0-9-]+_[0-9TZ]+_[a-zA-Z0-9]+\.json\.gz")
    return pattern.match(self.filename())

def records(self):
    """Returns CloudTrail Records in this log file"""
    logging.debug("Loading %s", self._path)

    try:
        with gzip.open(self._path, 'rt') as unzipped:
            json_data = json.load(unzipped)
            records = json_data['Records']
            return parse_records(records)
    except (IOError, OSError) as error:
        logging.warning("Could not load %s: %s", self._path, error)
        return []

def contains_events_for_timeframe(self, from_date, to_date):
    """Returns true if this logfile likely contains events in the relevant timeframe"""
    return from_date <= self.timestamp() <= to_date + datetime.timedelta(hours=1)

def _valid_log_files(self):
    def _valid_or_warn(log_file):
        if log_file.has_valid_filename():
            return True

        logging.warning("Invalid filename: %s", log_file.filename())
        return False

    def _to_paths(triple):
        root, _, files_in_dir = triple
        return [os.path.join(root, file_in_dir) for file_in_dir in files_in_dir]

    return pipe(os.walk(self._log_dir),
                mapcatz(_to_paths),
                mapz(LogFile),
                filterz(_valid_or_warn))

def load_from_dir(self, from_date, to_date):
    """Loads all CloudTrail Records in a file"""
    records = []
    for logfile in self._valid_log_files():
        if logfile.contains_events_for_timeframe(from_date, to_date):
            records.extend(logfile.records())

    return records

def _valid_or_warn(log_file):
    if log_file.has_valid_filename():
        return True

    logging.warning("Invalid filename: %s", log_file.filename())
    return False

def _by_timeframe(from_date, to_date):
    return lambda record: record.event_time is None or \
                          (from_date <= record.event_time <= to_date)

def _by_role_arns(arns_to_filter_for):
    if arns_to_filter_for is None:
        arns_to_filter_for = []

    return lambda record: (record.assumed_role_arn in arns_to_filter_for) or (len(arns_to_filter_for) == 0)

def load_from_api(self, from_date, to_date):
    """Loads the last 10 hours of cloudtrail events from the API"""
    client = boto3.client('cloudtrail')
    paginator = client.get_paginator('lookup_events')
    response_iterator = paginator.paginate(
        StartTime=from_date,
        EndTime=to_date,
    )
    records = []
    for response in response_iterator:
        for event in response['Events']:
            records.append(_parse_record(json.loads(event['CloudTrailEvent'])))

    return records

def _parse_record(json_record):
    try:
        return Record(json_record['eventSource'],
                      json_record['eventName'],
                      event_time=datetime.datetime.strptime(json_record['eventTime'],
                                                            "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=pytz.utc),
                      resource_arns=_resource_arns(json_record),
                      assumed_role_arn=_assumed_role_arn(json_record),
                      raw_source=json_record)
    except KeyError as error:
        logging.warning("Could not parse %s: %s", json_record, error)
        return None

