def __lt__(self, other):
    if self.Effect != other.Effect:
        return self.Effect < other.Effect
    if self.Action != other.Action:
        # pylint: disable=W0212
        return self.__action_list_strings() < other.__action_list_strings()

    return "".join(self.Resource) < "".join(other.Resource)

def __hash__(self):
    return hash((self.event_source,
                 self.event_name,
                 self.event_time,
                 tuple(self.resource_arns),
                 self.assumed_role_arn))

def _regex_sub(expr, subs):
    regex = re.compile(expr)
    return lambda s: regex.sub(subs, s)

def _s3_key_prefixes(prefix, org_ids, account_ids, regions, from_date, to_date):
    delta = to_date.astimezone(pytz.utc) - from_date.astimezone(pytz.utc)

    days = [to_date - datetime.timedelta(days=delta_days) for delta_days in range(delta.days + 1)]
    if org_ids:
        return [_s3_key_prefix_for_org_trails(prefix, day, org_id, account_id, region)
                for org_id in org_ids
                for account_id in account_ids
                for day in days
                for region in regions]

    return [_s3_key_prefix(prefix, day, account_id, region)
            for account_id in account_ids
            for day in days
            for region in regions]

